import{_ as r,a as t,b as o}from"./chunks/564889248446ea193cc0.BcsD0Ve3.js";import{_ as l}from"./chunks/ac945418977052fbacd6.CObdY42w.js";import{_ as i,C as n,o as s,c as h,j as e,a as m,E as d,a6 as c}from"./chunks/framework.CnPv4DE1.js";const P=JSON.parse('{"title":"我如何随时开启逆天专注力(四小时框架)","description":"","frontmatter":{"title":"我如何随时开启逆天专注力(四小时框架)","originalTitle":"How I Unlock Insane Focus On Demand (The 4 Hour Framework)","date":"2024-02-09","originalUrl":"https://thedankoe.com/letters/my-1-million-productivity-framework-the-4-hour-workday/","minutes":12,"sourceHash":"f011a966bd9412c74b23a77f4888ab5517ca482861182c266698eb8786dfda5c","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/my-1-million-productivity-framework-the-4-hour-workday/"}]]},"headers":[],"relativePath":"letters/my-1-million-productivity-framework-the-4-hour-workday.md","filePath":"letters/my-1-million-productivity-framework-the-4-hour-workday.md"}'),u={name:"letters/my-1-million-productivity-framework-the-4-hour-workday.md"};function f(k,p,b,g,_,y){const a=n("ArticleMeta");return s(),h("div",null,[p[0]||(p[0]=e("h1",{id:"我如何随时开启逆天专注力-四小时框架",tabindex:"-1"},[m("我如何随时开启逆天专注力(四小时框架) "),e("a",{class:"header-anchor",href:"#我如何随时开启逆天专注力-四小时框架","aria-label":'Permalink to "我如何随时开启逆天专注力(四小时框架)"'},"​")],-1)),d(a),p[1]||(p[1]=c('<p><a href="https://www.youtube.com/embed/5_PchY1xXlo?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>每天划出1个小时。</p><p>专注做1个有意义的项目。</p><p>为你的未来锚定1个愿景。</p><p>一次只过1天。</p><p>你不需要更多动力，你需要更多清晰。</p><p>你不需要更多时间，你需要更多专注。</p><p>这封信将教你如何随时开启逆天专注力。</p><p>大多数人以为自己需要像百万富翁那样工作才能实现目标。</p><p>但大多数人并不了解大多数百万富翁到底是怎么工作的。</p><p>两个例子：</p><p>第一个，OpenAI 的萨姆·奥特曼(Sam Altman)</p><p><img src="'+r+'" alt=""></p><p>第二个，泰吉·多萨(Tej Dosa)。一个低调的文案作者，在 X 上写着很棒的内容：</p><p><img src="'+t+'" alt=""></p><p>第三个，我自己。</p><p>所以不，你并不需要比你现在拥有的更多的时间。</p><p><em>每个人都是从某个起点开始的。人们不是从一个假想的百万富翁式作息开始的。他们是从自己所拥有的东西开始的。</em></p><p>除了搭建新项目的时候，<em>我很少每天工作超过4个小时。</em></p><p>尤其是在我刚起步、还有其他责任要承担的时候。</p><p>我每天只有1到2个小时，休息日会稍微多一点。</p><p>那些工作更长时间的创业者，是他们自己做出的选择，往往是以心理代价为交换的。</p><p>生产力就像健身一样，你不会每天不吃不睡地训练8个小时，还指望能取得进步。</p><p>工作分为两种类型：</p><ol><li><strong>构建</strong> —— 当你在打造某个新事物的基础时。比如一款产品、一项服务，或一个品牌。<strong>这需要大量的前期投入。</strong></li><li><strong>维护</strong> —— 当你用一套精简的生产力系统来为已建成的基础持续输出燃料时。比如写内容、做自我营销、经营受众，或交付你的产品或服务。<strong>这只需要每天1到4小时，取决于你的技能水平或你所<em>选择</em>的工作类型。</strong></li></ol><p>那些想要改变生活或辞职的人，常常会被“构建”所需的工作量吓退。</p><p>他们无法把视角拉远，去意识到一旦建成之后，你的工作量会大幅下降。</p><p>专注力是会复利增长的。</p><p>随着时间推移，你在自己做的事情上会变得越来越擅长。</p><p>就像学走路一样，一开始很难。从你所在的地方走到你想去的地方需要更多时间。</p><p>但当你不断尝试、失败，让你那具有自我纠正能力的大脑重新连接出新的神经通路后，你就能以你想要的速度走过去……甚至干脆冲刺。</p><p>如果你想了解我关于专注生活的完整理念，去拿我的书<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">《专注的艺术》(The Art Of Focus)</a>。</p><p>专注地工作只是改变人生的一部分。</p><h2 id="你的大脑是一台运行-人生游戏-的超级计算机" tabindex="-1">你的大脑是一台运行“人生游戏”的超级计算机 <a class="header-anchor" href="#你的大脑是一台运行-人生游戏-的超级计算机" aria-label="Permalink to &quot;你的大脑是一台运行“人生游戏”的超级计算机&quot;">​</a></h2><p>你的大脑是一台超级计算机。</p><p>你的注意力就是它的内存(RAM)。</p><p>那些念头、遗憾和待办事项，是拖慢你性能的一个个后台程序。</p><p>写作、正念和专注，则是你随时都能启动的“重启”功能。</p><p>RAM——也就是“随机存取存储器”——是电脑最重要的部件之一，它决定着性能表现。</p><p>你运行的程序越多、打开的浏览器标签越多、当下运行任务对性能的要求越高，你所消耗的内存就越多，性能就越慢。</p><p>这和你的专注力没什么不同——也就是你在意识中所占据的那部分内容。</p><p>人类每秒能处理50比特信息。一生累积起来，那就是1250亿比特的信息量。</p><p>大多数人的生活里同时运行着多个高负荷的“程序”，正在不断耗尽他们本就有限的创造性能量。</p><ul><li>对过去令人懊悔的错误的念头</li><li>对未来令人焦虑的事情的念头</li><li>为了逃避这些念头而产生的贪食和娱乐欲望</li><li>一种想要打破自身被规训生活方式的内心呼喊</li><li>一份优先级混乱、亟需完成的任务清单</li><li>本该完成却被遗忘的、悬而未决的事项循环</li></ul><p>这份清单可以无限列下去。</p><p>现代人的心智，默认就把注意力分裂到了无数个方向。</p><p>我们过着充满压力、几近病态的生活。本该以单一专注和无忧无虑的心态活在当下，可我们恰恰相反。我们活在一个由分裂的注意力所制造出来的虚假现实中。</p><p>当我们的意识内容中承载了太多的过去或未来时,混乱便会滋生。心智天生就趋向无序。如果不加以约束，我们就会失去对生活的掌控感——而这种掌控感正是愉悦感的来源。要做到这一点，需要靠受控的意识。</p><h2 id="心理熵-分心带来的危险" tabindex="-1">心理熵：分心带来的危险 <a class="header-anchor" href="#心理熵-分心带来的危险" aria-label="Permalink to &quot;心理熵：分心带来的危险&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p><em>熵是宇宙至高无上的法则。</em></p><p>不把话说得太复杂：如果你不投入精力去解决问题、维持一个系统的秩序，这个系统就会逐渐走向混乱。</p><p>如果你不花力气去整理你的书架，书本就会散落在你家的各个角落、朋友家里，一场小规模的混乱就此展开。</p><p>如果你不花力气去维护打扫房间这件事，房间就会越来越脏，直到你生活在一个令人作呕的垃圾窝里。</p><p>这正是大多数人大脑此刻的状态。</p><p><em>一个令人作呕的垃圾窝。</em></p><p>心理熵，是指你的心灵(或大脑)自然而然趋向混乱和无序的过程。</p><p>你效率不高，是因为你缺乏清晰感。</p><p>你效率不高，是因为你的注意力被某个分心事物牢牢锁住，你没有及时纠正自己，慢慢地就被脑中的混乱彻底淹没了。</p><p>分心，是你生产力系统中必须解决的问题——如果你想要开启激光般的专注力，就必须解决它们。</p><p>有两种方式可以识别分心并纠正自己：</p><p><strong>无聊和焦虑。</strong></p><p><img src="'+l+'" alt=""></p><p>如果你正在做的任务的难度对你的技能水平来说太低，你就会感到无聊。</p><p>如果你正在做的任务的难度对你的技能水平来说太高，你就会感到焦虑。</p><p><strong>无聊</strong>源于以自我为中心。</p><p>你的注意力被打断，一个新的欲望突然冒出脑海，相关的念头开始占据你的注意力。</p><p>如果你对手头的任务感到无聊，你就会开始想那些你本可以去做的、更“好”的事情。</p><p><strong>焦虑</strong>源于自我意识过强。</p><p>你的注意力转向内在，大脑里充斥着“我不够好”之类的负面念头。</p><p>如果你照镜子发现脸上长了个痘，那这件事会在你剩下的一整天里一直挂在心头。它会影响你生活的方方面面。</p><p>你这台心理超级计算机的内存，会被这些不请自来的“程序”耗尽，直到你的整体表现受到拖累。</p><p>由无聊或焦虑引发的混乱，唯有靠清晰感才能治愈。</p><p>你必须重新聚焦你的大脑——不仅要专注于眼前的任务，还要专注于你整个人生所追求的理想结果。</p><p>当你的技能和知识水平与任务的挑战难度相匹配时，人生就变成了一场你热爱玩的、由一个个任务组成的电子游戏。</p><h2 id="四小时工作日——打造你的生产力系统" tabindex="-1">四小时工作日——打造你的生产力系统 <a class="header-anchor" href="#四小时工作日——打造你的生产力系统" aria-label="Permalink to &quot;四小时工作日——打造你的生产力系统&quot;">​</a></h2><p>人类从故事中寻找意义。</p><p>人类热爱玩游戏。</p><p>为什么？</p><p>因为它们呈现出一套清晰的目标层级，我们的大脑可以将其当作一个不受干扰的思维框架而采纳。</p><p>它们遵循着宇宙的“好奇 &gt; 强烈投入 &gt; 持续稳定”循环。</p><p>一开始你会迷失方向。然后你产生好奇。然后你变得痴迷。再然后，它就毫不费力地成为你生活中恒常的一部分。</p><p>大多数人会迷失方向、把注意力放在各种分心事物上，从不愿为一个目标付出努力(即便他们暂时还看不出其中的意义)，去扭转他们正在为自己挖的坑。</p><p>要明白，没有任何东西是完美的。</p><p>就像一个故事一样，你会经历低谷，但正是这些低谷，才让高潮得以存在。没有失败，就没有成功。</p><p>就像一场电子游戏，你必须通过完成一系列任务来升级，从新手一步步进阶到高手。这需要时间。</p><p>如果你想在工作中获得最大程度的愉悦感和专注力，下面这些准则会帮你为你的生产力系统建立起一套目标层级。</p><p>你坚持得越久，它就会变得越强大。</p><h3 id="身份认同——解决生产性问题" tabindex="-1">身份认同——解决生产性问题 <a class="header-anchor" href="#身份认同——解决生产性问题" aria-label="Permalink to &quot;身份认同——解决生产性问题&quot;">​</a></h3><p>从我记事起，我心中就一直有一个目标：每天只工作4个小时。</p><p>朝九晚五的工作，是我生命中的头号大敌。</p><ul><li>我观察社会，看清了我不想要的那种生活</li><li>我观察那些成功的人，看清了我想要的那种生活</li></ul><p>随着时间推移，这种视角塑造了我的身份认同。</p><p>我对那份渴望有着深深的执念。</p><p>大多数人会告诉你欲望是不好的，但在我看来，只有当欲望本身是坏的时候，它才是不好的。</p><p>你的目标，是你痛苦的轴心，而你能够选择的是——你要为什么样的东西而痛苦。</p><p>视角决定一切。</p><p>它让你能够识别出那些问题和机会——一旦解决(或抓住)这些问题和机会，就能实现该视角所对应的目标。</p><p>能走到今天这一步，对我来说几乎是一个自动发生的决定。</p><p>任何威胁到我“每天工作4小时”这一目标的事情，都会被我标记为一个问题。</p><p>我因此能够发现像社交媒体、数字产品、经营受众这样的机会，来解决那些问题。</p><p>大多数人的身份认同和视角是被社会塑造出来的，怀揣着社会所设定的目标，所以他们从来无法识别并解决那些能带来非凡结果的问题。</p><h3 id="项目——挖掘你的潜力" tabindex="-1">项目——挖掘你的潜力 <a class="header-anchor" href="#项目——挖掘你的潜力" aria-label="Permalink to &quot;项目——挖掘你的潜力&quot;">​</a></h3><p>你的身份认同，是由你对未来的愿景塑造出来的。</p><p>你的愿景，是你一生所追求的那个包罗万象的总目标。它位于你目标层级的最顶端。一切都归属于它之下。</p><p>现在，你需要一个能推动你朝那个未来前进的项目。</p><p>你需要有一些东西可以去<em>构建</em>，从而让你暴露在必须解决的问题面前。</p><p>你需要为你的工作确立清晰性，这样你才有一个东西能锚定你的注意力。</p><p>而如果你读过<a href="/letters/i-discovered-a-way-to-learn-10x-faster-reality-metabolism-universal-thinking">上一封信</a>，你就会明白，构建一个项目是学习新知识和新技能的最佳方式。</p><ol><li><strong>列一份大纲</strong> —— 把你<em>知道</em>的、应该被建进这个项目里的一切都倾倒出来。随着你不断构建，你会持续往这份大纲里添加内容。</li><li><strong>设定里程碑</strong> —— 把这个项目拆解成一个个可管理的小目标，让你能在1到4小时的一次工作时段内完成，具体取决于你当前的责任负担。</li></ol><p>你的项目应该是什么？</p><p>这个我没法告诉你。</p><p>但它大概应该是一份事业，因为事业是承载你人生目的的载体。它是那个能把你从机械化生活中解救出来、通向美好人生的催化剂。创业，就是现代版的生存狩猎，而你的心灵天生就是为狩猎而设计的。你不该是被关在格子间里的一只猴子。</p><p>与此同时，你的健康和人际关系，同样是重要的“项目”，它们能提升你事业上的成果。</p><h3 id="截止期限——拖延者的优势" tabindex="-1">截止期限——拖延者的优势 <a class="header-anchor" href="#截止期限——拖延者的优势" aria-label="Permalink to &quot;截止期限——拖延者的优势&quot;">​</a></h3><p>你效率不高，是因为你没有公开曝光。</p><p>这又是一个在社交媒体上创建互联网事业的理由。挑战与截止期限所要求的那种心流状态，天然内置其中。</p><p>当我为一款产品设定发布日期并开放预售后，一旦第一个人付了钱，我就<em>必须</em>在截止日期前把这个产品做出来。</p><p>至于它做得好不好，其实无关紧要。</p><p>我可以事后再去改进它，因为它已经真正问世了，而我也确实用自己的人生做成了一件事。</p><p>还有一点：</p><p>拖延并不是坏事。它是人的本性。</p><p>大多数成功的创业者其实都很懒。</p><p>他们总是拖到最后一刻才把事情做完。</p><p>但在那最后一分钟里，他们进入了生命中最享受的时期。他们的大脑变成了吸引创意的磁铁。他们最好的作品就诞生在这些痴迷和高强度的时期。</p><p>他们别无选择，因为这关乎他们的生存。</p><h3 id="时间块与休息——管理你的注意力" tabindex="-1">时间块与休息——管理你的注意力 <a class="header-anchor" href="#时间块与休息——管理你的注意力" aria-label="Permalink to &quot;时间块与休息——管理你的注意力&quot;">​</a></h3><blockquote><p>注意力就像肌肉，成功是为那些锻炼它的人准备的。——《注意力的艺术》（The Art Of Focus）</p></blockquote><p>身份、项目和截止日期会收拢你的注意力。</p><p>时间块在此基础上更进一步，让你轻松进入心流。</p><p>设定一个45到90分钟的计时器。</p><p>保持高强度专注。</p><p>然后，休息一下。</p><p>去散散步。吃点东西。看会儿YouTube。打会儿电子游戏。我不在乎你做什么。</p><p>你的注意力是有限的。你需要在每一组专注之间休息。</p><p>就我个人而言，我<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">在两个60分钟的时间块里写作</a>。正是这些构建了我的整个业务。</p><h3 id="杠杆——做正确的事" tabindex="-1">杠杆——做正确的事 <a class="header-anchor" href="#杠杆——做正确的事" aria-label="Permalink to &quot;杠杆——做正确的事&quot;">​</a></h3><p>我要帮你免去很多痛苦：</p><p>选择一份允许你每天只工作4小时的职业。</p><p>创办一家<a href="/letters/the-one-person-business-model-how-to-monetize-yourself">一人企业</a>。成为一名<a href="https://university.kortex.co/" target="_blank" rel="noreferrer">价值创作者</a>。利用互联网去做你热爱的事。</p><p>学习能够实现这一点的技能。</p><p>进化是解决能够逆转熵的问题的过程。</p><p>纯体力劳动和漫长的工作日是一个巨大的问题。人们讨厌它。因此，社交媒体、互联网和人工智能诞生了。</p><p>人工智能将解决过度工作的问题。很可能就在我们有生之年（特别是如果我们还能解决衰老问题的话）。</p><p>现在，你每天的工作环节应该包含3-9项能够撬动杠杆、推进你项目的任务。</p><p>有些人能处理更多，有些人则少一些。我在<a href="https://thedankoe.store/products/the-foci-planner" target="_blank" rel="noreferrer">FOCI计划本</a>中帮你梳理了这种结构。</p><h3 id="日常惯例——变得高效" tabindex="-1">日常惯例——变得高效 <a class="header-anchor" href="#日常惯例——变得高效" aria-label="Permalink to &quot;日常惯例——变得高效&quot;">​</a></h3><p>你是有日常惯例的。</p><p>哪怕你的日常惯例就是“没有惯例”。</p><p>我们在<a href="/letters/the-daily-routine-that-changed-my-life-4-focus-habits">《改变我生活的日常作息》</a>中讨论过这一点。</p><p>日常惯例是你训练大脑在全新系统上运行的方式。</p><p>如果你想巩固一个新的身份，你必须开始建立、不断完善并坚持一项日常惯例。</p><p>在第一个月，构建你的项目会让你感到不舒服。</p><p>你理应感到不知所措。这意味着你的心智正在扩展，融入一个新的身份。</p><p>起初很慢，然后突然之间，一切都变得轻松流畅。</p><p>你开始取得指数级的进步。</p><p>你从高强度转变为保持一致性，并让结果产生复利。</p><h3 id="休息——伟人们的秘密" tabindex="-1">休息——伟人们的秘密 <a class="header-anchor" href="#休息——伟人们的秘密" aria-label="Permalink to &quot;休息——伟人们的秘密&quot;">​</a></h3><blockquote><p><em>“人们常说，聪明人工作靠巧劲，而不是靠死力气，但有创造力的人压根就不工作。”——亚历克斯·索钟-金·庞（Alex Soojung-Kim Pang）</em></p></blockquote><p>我一直对西方的职场文化有一种排斥。</p><ul><li>每周工作80小时。</li><li>高压环境。</li><li>几乎没有时间休息和恢复。</li></ul><p>对我来说，这感觉从来都不“对”。</p><p>既然知道工作2-3小时后我的工作质量就会下降，我为什么还要浪费整天的时间呢？</p><p>长期以来，这一直是个热门话题。我相信它已经开始塑造创作者经济和远程工作了。</p><p>古罗马人、古希腊人、史蒂夫·乔布斯（Steve Jobs）、查尔斯·达尔文（Charles Darwin），以及无数的远见卓识者、战略家和创新者，都将他们的成功归结于短得惊人的“工作”时间。</p><p>各领域的作家，比如海明威（Hemingway）和塔伦蒂诺（Tarantino），会把他们每天大部分时间花在泳池边闲逛、跟女孩搭讪，做着一切除了他们所谓的“工作”之外的事情。</p><p>工作1到4小时。</p><p>然后，停下来。</p><p>这可以说是你一天中最困难的部分。</p><p>在工作环节结束时，我会去健身房，作为进入休息状态的一种“过渡”。</p><p>这会让默认模式网络（Default Mode Network）开始发挥作用。我的潜意识开始咀嚼那些与工作相关的问题。</p><p>当我重新回到早晨的专注工作时，我已经储备了所需的休息和创意资源，这让我那4个小时的工作，比那些把心智肌肉榨干到令人难以置信程度的人所做的工作，要有效力得多。</p><p>朋友们，希望你们喜欢这封信。</p><p>丹 (Dan)</p><hr><p><a href="/en/letters/my-1-million-productivity-framework-the-4-hour-workday">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',176))])}const T=i(u,[["render",f]]);export{P as __pageData,T as default};
